-- ==========================================
-- SOUNDVIBE SUPABASE (POSTGRESQL) MIGRATION
-- Database: Supabase PostgreSQL
-- Authentication: Firebase Auth (UIDs as IDs)
-- ==========================================

-- 1. DROP EXISTING TABLES IF RE-RUNNING
DROP TABLE IF EXISTS public.reactions CASCADE;
DROP TABLE IF EXISTS public.comments CASCADE;
DROP TABLE IF EXISTS public.follows CASCADE;
DROP TABLE IF EXISTS public.posts CASCADE;
DROP TABLE IF EXISTS public.profiles CASCADE;

-- 2. PROFILES TABLE (Stores Firebase Auth UID as primary key)
CREATE TABLE public.profiles (
  id TEXT PRIMARY KEY, -- Firebase Auth UID (e.g. '2J8VmV1rBKMlJEnBvKWQN1MBklI2')
  username TEXT UNIQUE NOT NULL,
  name TEXT,
  email TEXT,
  avatar TEXT,
  bio TEXT DEFAULT 'Music enthusiast sharing sonic vibes on SoundVibe 🎧',
  favorite_genres TEXT[] DEFAULT ARRAY['Indie Rock', 'Electronic'],
  badges TEXT[] DEFAULT ARRAY['Curator'],
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);

-- 3. POSTS TABLE
CREATE TABLE public.posts (
  id TEXT PRIMARY KEY DEFAULT ('post_' || replace(gen_random_uuid()::text, '-', '')), -- Preserves Firestore doc ID or auto-generates
  user_id TEXT NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  track JSONB NOT NULL,
  rating INT CHECK (rating >= 1 AND rating <= 5),
  headline TEXT,
  review TEXT,
  favorite_lyric TEXT,
  vibe_tags TEXT[] DEFAULT '{}',
  mood TEXT,
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);

-- 4. REACTIONS TABLE (Atomic 1-reaction per user per type)
CREATE TABLE public.reactions (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  post_id TEXT NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  reaction_type TEXT NOT NULL CHECK (reaction_type IN ('fire', 'vibe', 'heart', 'repeat', 'mindblown', 'overrated')),
  created_at TIMESTAMPTZ DEFAULT now(),
  UNIQUE(post_id, user_id, reaction_type)
);

-- 5. COMMENTS TABLE
CREATE TABLE public.comments (
  id TEXT PRIMARY KEY DEFAULT ('comm_' || replace(gen_random_uuid()::text, '-', '')),
  post_id TEXT NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  text TEXT NOT NULL,
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now()
);

-- 6. FOLLOWS TABLE (Relational Social Graph)
CREATE TABLE public.follows (
  follower_id TEXT NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  following_id TEXT NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY (follower_id, following_id),
  CHECK (follower_id <> following_id)
);

-- 7. PERFORMANCE INDEXES
CREATE INDEX idx_posts_user_id ON public.posts(user_id);
CREATE INDEX idx_posts_created_at ON public.posts(created_at DESC);
CREATE INDEX idx_reactions_post_id ON public.reactions(post_id);
CREATE INDEX idx_comments_post_id ON public.comments(post_id);
CREATE INDEX idx_follows_follower ON public.follows(follower_id);
CREATE INDEX idx_follows_following ON public.follows(following_id);
CREATE INDEX idx_profiles_username ON public.profiles(username);

-- 8. ROW LEVEL SECURITY (RLS) POLICIES
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.posts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.comments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.follows ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow public read on profiles" ON public.profiles FOR SELECT USING (true);
CREATE POLICY "Allow anon insert/update on profiles" ON public.profiles FOR ALL USING (true) WITH CHECK (true);

CREATE POLICY "Allow public read on posts" ON public.posts FOR SELECT USING (true);
CREATE POLICY "Allow anon insert/update on posts" ON public.posts FOR ALL USING (true) WITH CHECK (true);

CREATE POLICY "Allow public read on reactions" ON public.reactions FOR SELECT USING (true);
CREATE POLICY "Allow anon insert/update on reactions" ON public.reactions FOR ALL USING (true) WITH CHECK (true);

CREATE POLICY "Allow public read on comments" ON public.comments FOR SELECT USING (true);
CREATE POLICY "Allow anon insert/update on comments" ON public.comments FOR ALL USING (true) WITH CHECK (true);

CREATE POLICY "Allow public read on follows" ON public.follows FOR SELECT USING (true);
CREATE POLICY "Allow anon insert/update on follows" ON public.follows FOR ALL USING (true) WITH CHECK (true);

