VALUES ('Ci58mBTUA6zuQhc59nWl', 'kwXsKn7BsgYDrGVnEKSodnfAepi1', '{"trackViewUrl":"https://music.apple.com/us/album/the-karma-theme-from-u-turn/1445554976?i=1445555278&uo=4","id":"itunes-1445555278","album":"Best of 2018 (Tamil)","youtubeMusicUrl":"https://music.youtube.com/search?q=Anirudh%20Ravichander%20The%20Karma%20Theme%20(From%20%22U%20Turn%22)","youtubeSearchUrl":"https://www.youtube.com/results?search_query=Anirudh%20Ravichander%20The%20Karma%20Theme%20(From%20%22U%20Turn%22)%20official%20audio","youtubeEmbedUrl":"https://www.youtube-nocookie.com/embed?listType=search&list=Anirudh%20Ravichander%20The%20Karma%20Theme%20(From%20%22U%20Turn%22)&autoplay=1","title":"The Karma Theme (From \"U Turn\")","durationMs":214500,"previewUrl":"https://audio-ssl.itunes.apple.com/itunes-assets/AudioPreview211/v4/0a/d9/a3/0ad9a30b-e295-cc6d-2c7e-f40322e61adb/mzaf_3080821503123185110.plus.aac.p.m4a","artwork":"https://is1-ssl.mzstatic.com/image/thumb/Music128/v4/d3/42/29/d34229f2-e7d7-c3a0-48aa-a75724362cd9/886447469958.jpg/600x600bb.jpg","artist":"Anirudh Ravichander","genre":"Tamil"}'::jsonb, 5, 'Some songs don’t leave you when they end...', 'There’s something about this song that stays with me. The vocals, the lyrics, the whole mood… it feels like memories, fate, and something you can’t quite let go of... 🖤', 'Un sirippukku vithai… Neethan...', 'Reflective', ARRAY['#HeavyRotation', '#MidnightDrive', '#HiddenGem', '#HeartbreakAnthem', '#Nostalgia', '#Masterpiece']::text[], '2026-08-31T19:07:33.474Z'::timestamptz)
