INSERT INTO public.posts (id, user_id, track, rating, headline, review, favorite_lyric, mood, vibe_tags, created_at)
VALUES ('HgyDSVwXX89o5KNzmGjT', 'Qc7DluumNTWUnKFwURPr1LYnBPh1', '{"genre":"Telugu","youtubeEmbedUrl":"https://www.youtube-nocookie.com/embed?listType=search&list=S.S.%20Thaman%20Veera%20Skanda&autoplay=1","youtubeMusicUrl":"https://music.youtube.com/search?q=S.S.%20Thaman%20Veera%20Skanda","title":"Veera Skanda","durationMs":103174,"previewUrl":"https://audio-ssl.itunes.apple.com/itunes-assets/AudioPreview112/v4/80/81/d0/8081d0e3-8e0d-fb4b-706c-3d399edefaff/mzaf_9782377582945551466.plus.aac.p.m4a","id":"itunes-1734810450","trackViewUrl":"https://music.apple.com/us/album/veera-skanda/1734809113?i=1734810450&uo=4","artist":"S.S. Thaman","album":"Skanda (Orginal Background Score)","artwork":"https://is1-ssl.mzstatic.com/image/thumb/Music211/v4/06/bc/b7/06bcb797-1dbc-d5a6-5deb-9bae2c3f2076/8902633353442.jpg/600x600bb.jpg","youtubeSearchUrl":"https://www.youtube.com/results?search_query=S.S.%20Thaman%20Veera%20Skanda%20official%20audio"}'::jsonb, 5, 'Warrior Song', 'I like this song a lot. It mentions Lord Shri Ram. One of the favorite characters with so many adorable qualities. He is the perfect mix of passion and restraint. He destroyed Raavan completely after he abducted Seeta Mata. That is his passion for his beloved. But at the same time. He also gave every possible chance for him to correct his mistake peacefully, in spite of being immensely powerful. That is his restraint and humbleness. Absolutely the perfect combo.', '', 'Euphoric', ARRAY['#HeavyRotation', '#MidnightDrive', '#GymHype']::text[], '2026-09-08T18:47:40.776Z'::timestamptz)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.posts (id, user_id, track, rating, headline, review, favorite_lyric, mood, vibe_tags, created_at)
VALUES ('L9KqsN2nRokwQhVsTTZC', 'kwXsKn7BsgYDrGVnEKSodnfAepi1', '{"durationMs":189567,"youtubeMusicUrl":"https://music.youtube.com/search?q=Kala%20Bhairava%2C%20Ananthu%2C%20Gowtham%20Bharadwaj%20%26%20Chandra%20Bose%20Theme%20Of%20Kalki","previewUrl":"https://audio-ssl.itunes.apple.com/itunes-assets/AudioPreview221/v4/d4/02/97/d402978e-2412-ba38-4b95-3becb6adff52/mzaf_1213384824151512083.plus.aac.p.m4a","youtubeEmbedUrl":"https://www.youtube-nocookie.com/embed?listType=search&list=Kala%20Bhairava%2C%20Ananthu%2C%20Gowtham%20Bharadwaj%20%26%20Chandra%20Bose%20Theme%20Of%20Kalki&autoplay=1","album":"Kalki 2898 AD (Original Motion Picture Soundtrack)","artist":"Kala Bhairava, Ananthu, Gowtham Bharadwaj & Chandra Bose","genre":"Telugu","artwork":"https://is1-ssl.mzstatic.com/image/thumb/Music221/v4/7f/1c/51/7f1c518d-4311-3fd6-a610-f4acab73e7e0/198588725511.jpg/600x600bb.jpg","trackViewUrl":"https://music.apple.com/us/album/theme-of-kalki/1756881322?i=1756881333&uo=4","id":"itunes-1756881333","youtubeSearchUrl":"https://www.youtube.com/results?search_query=Kala%20Bhairava%2C%20Ananthu%2C%20Gowtham%20Bharadwaj%20%26%20Chandra%20Bose%20Theme%20Of%20Kalki%20official%20audio","title":"Theme Of Kalki"}'::jsonb, 5, 'There’s something about this song… ✨', 'There’s something about this song… the vocals, the build-up, the whole energy just gives me chills. It feels powerful and divine at the same time. I don’t know how to explain it, but every time I hear it, I just get that feeling again. ❤️‍🔥', '', 'Energetic', ARRAY['#HeavyRotation', '#Masterpiece', '#GymHype', '#Nostalgia', '#HiddenGem']::text[], '2026-08-31T18:28:21.596Z'::timestamptz)
