VALUES ('VWqu1TL0lY0zasI6ZhjD', 'kwXsKn7BsgYDrGVnEKSodnfAepi1', '{"youtubeSearchUrl":"https://www.youtube.com/results?search_query=Ghibran%20%26%20Sathya%20Prakash%20Kalabhairavashtakam%20-%20Lord%20Kala%20Bhairava%20(From%20%22Ghibran''s%20Spiritual%20Series%22)%20official%20audio","id":"itunes-1523928876","title":"Kalabhairavashtakam - Lord Kala Bhairava (From \"Ghibran''s Spiritual Series\")","trackViewUrl":"https://music.apple.com/us/album/kalabhairavashtakam-lord-kala-bhairava-from-ghibrans/1523928580?i=1523928876&uo=4","genre":"Devotional & Spiritual","previewUrl":"https://audio-ssl.itunes.apple.com/itunes-assets/AudioPreview125/v4/b1/51/9f/b1519fe9-f8e0-83f7-78ef-5ac656613b05/mzaf_17415801924416409728.plus.aac.p.m4a","durationMs":260182,"album":"Kalabhairavashtakam - Lord Kala Bhairava (From \"Ghibran''s Spiritual Series\") - Single","artist":"Ghibran & Sathya Prakash","youtubeMusicUrl":"https://music.youtube.com/search?q=Ghibran%20%26%20Sathya%20Prakash%20Kalabhairavashtakam%20-%20Lord%20Kala%20Bhairava%20(From%20%22Ghibran''s%20Spiritual%20Series%22)","artwork":"https://is1-ssl.mzstatic.com/image/thumb/Music114/v4/62/ce/63/62ce63e8-41c4-fdd9-4bcf-4e404a81dd49/cover.jpg/600x600bb.jpg","youtubeEmbedUrl":"https://www.youtube-nocookie.com/embed?listType=search&list=Ghibran%20%26%20Sathya%20Prakash%20Kalabhairavashtakam%20-%20Lord%20Kala%20Bhairava%20(From%20%22Ghibran''s%20Spiritual%20Series%22)&autoplay=1"}'::jsonb, 5, 'My day doesn’t begin without this. 🕉️', 'I listen to this every morning when I wake up, usually before 5. It has become my way of starting the day with a calm mind, a clear heart, and the right energy. 🕉️❤️', 'Kāśikāpura-adinātha Kālabhairavaṁ bhaje.', 'Euphoric', ARRAY['#HeavyRotation', '#Masterpiece', '#Reflective', '#ChillRelaxed', '#Nostalgia']::text[], '2026-09-02T10:47:55.229Z'::timestamptz)
