VALUES ('hV2Ryu8pRt6FgL97eICU', 'XL14bAKPlNPR9P3NXkRNq5UvwSc2', '{"youtubeEmbedUrl":"https://www.youtube-nocookie.com/embed?listType=search&list=Himesh%20Reshammiya%20%26%20Hariharan%20Kallaimattum%20Kandal&autoplay=1","youtubeMusicUrl":"https://music.youtube.com/search?q=Himesh%20Reshammiya%20%26%20Hariharan%20Kallaimattum%20Kandal","album":"Dhasavathaaram (Original Motion Picture Soundtrack)","artist":"Himesh Reshammiya & Hariharan","genre":"Tamil","artwork":"https://is1-ssl.mzstatic.com/image/thumb/Features/14/65/21/dj.fikrplde.jpg/600x600bb.jpg","previewUrl":"https://audio-ssl.itunes.apple.com/itunes-assets/AudioPreview115/v4/07/15/b0/0715b01a-3d53-52a1-8ae9-486084984ba5/mzaf_4555210654936320503.plus.aac.p.m4a","trackViewUrl":"https://music.apple.com/us/album/kallaimattum-kandal/311674289?i=311674295&uo=4","durationMs":328080,"id":"itunes-311674295","title":"Kallaimattum Kandal","youtubeSearchUrl":"https://www.youtube.com/results?search_query=Himesh%20Reshammiya%20%26%20Hariharan%20Kallaimattum%20Kandal%20official%20audio"}'::jsonb, 5, 'My childhood fav 💖', 'This song made my childhood days. In the beginning of the song there will be utterence of Om Namo Narayana for 30 sec breathlessly that makes me feel goosebumps everytime I hear.', 'Naattil undu aayiram Rajarajan dhaan Rajanukku rajan Indha rangarajan dhaan', 'Energetic', ARRAY['#HeavyRotation', '#MidnightDrive', '#Masterpiece']::text[], '2026-09-01T13:50:34.987Z'::timestamptz)
