VALUES ('hh53GE53QSX0Vo7jPZdJ', 'AN1qeVm9SLei40yYF6Kjht81Hls2', '{"youtubeMusicUrl":"https://music.youtube.com/search?q=Shashwat%20Sachdev%2C%20Token%2C%20Vaibhav%20Gupta%2C%20Shahzad%20Ali%20%26%20Traditional%20Destiny%20-%20Mann%20Atkeya","album":"Dhurandhar The Revenge (Original Motion Picture Soundtrack)","artwork":"https://is1-ssl.mzstatic.com/image/thumb/Music221/v4/89/74/08/897408d1-39d9-5d32-06a8-256ea77e4158/8902894362900_cover.jpg/600x600bb.jpg","youtubeEmbedUrl":"https://www.youtube-nocookie.com/embed?listType=search&list=Shashwat%20Sachdev%2C%20Token%2C%20Vaibhav%20Gupta%2C%20Shahzad%20Ali%20%26%20Traditional%20Destiny%20-%20Mann%20Atkeya&autoplay=1","trackViewUrl":"https://music.apple.com/us/album/destiny-mann-atkeya/1885907871?i=1885907880&uo=4","youtubeSearchUrl":"https://www.youtube.com/results?search_query=Shashwat%20Sachdev%2C%20Token%2C%20Vaibhav%20Gupta%2C%20Shahzad%20Ali%20%26%20Traditional%20Destiny%20-%20Mann%20Atkeya%20official%20audio","artist":"Shashwat Sachdev, Token, Vaibhav Gupta, Shahzad Ali & Traditional","durationMs":226104,"previewUrl":"https://audio-ssl.itunes.apple.com/itunes-assets/AudioPreview221/v4/da/02/4b/da024b2f-b89c-2414-7fed-4cdca4cb89db/mzaf_17579668594764035312.plus.aac.p.m4a","title":"Destiny - Mann Atkeya","id":"itunes-1885907880","genre":"Bollywood"}'::jsonb, 5, 'A relentless anthem for anyone chasing their destiny', 'A powerful fusion of hard-hitting rap, cinematic production and soulful Punjabi vocals. The track turns pain, rejection and self-doubt into pure determination. “Never quit” isn''t just a lyric here—it feels like the entire philosophy of the song.', 'Man ki ichha pooran kar do, bairagi behaal , Man atkeya beparwah de naal', 'Energetic', ARRAY['#HeavyRotation', '#HiddenGem', '#GymHype']::text[], '2026-09-01T14:56:52.244Z'::timestamptz)
