INSERT INTO public.posts (id, user_id, track, rating, headline, review, favorite_lyric, mood, vibe_tags, created_at)
VALUES ('oVqqir0Fmg5UYdsjgguS', 'UfkHjHpmNyQFwPmEaOzdNfW5kYU2', '{"album":"Greatest Hits, Vol. 2","artwork":"https://is1-ssl.mzstatic.com/image/thumb/Music125/v4/af/c3/c6/afc3c6c5-23f3-363e-afba-7f30adda2c91/00016351660824_Cover.jpg/600x600bb.jpg","trackViewUrl":"https://music.apple.com/us/album/sanson-ki-mala/1564912672?i=1564913034&uo=4","id":"itunes-1564913034","artist":"Nusrat Fateh Ali Khan","youtubeSearchUrl":"https://www.youtube.com/results?search_query=Nusrat%20Fateh%20Ali%20Khan%20Sanson%20Ki%20Mala%20official%20audio","previewUrl":"https://audio-ssl.itunes.apple.com/itunes-assets/AudioPreview125/v4/42/03/65/42036560-e142-6bbe-047d-e0cd21f11a99/mzaf_13750379909344338247.plus.aac.p.m4a","youtubeMusicUrl":"https://music.youtube.com/search?q=Nusrat%20Fateh%20Ali%20Khan%20Sanson%20Ki%20Mala","title":"Sanson Ki Mala","durationMs":1242871,"genre":"Worldwide","youtubeEmbedUrl":"https://www.youtube-nocookie.com/embed?listType=search&list=Nusrat%20Fateh%20Ali%20Khan%20Sanson%20Ki%20Mala&autoplay=1"}'::jsonb, 5, 'Pure vocal transcendence and timeless spiritual ecstasy.', 'Nusrat Fateh Ali Khan turns devotion into an overwhelming emotional experience. The gradual build-up from rhythmic harmonium chords and hypnotic tabla beats into soaring vocal improvisations (sargam) creates a trance-like state that is impossible to replicate. It isn''t just a song; it''s pure raw energy and spiritual immersion.', 'Prem ke rang mein aisi doobi, ban gaya ek hi roop  Prem ki maala japte japte, aap bani main Shyam....................Duniya chahe jo bhi bole, mujhko kisi se kya  Dhan, daulat, sukh sab chhod diya, bas manga prem ka daan', 'Euphoric', ARRAY['#Masterpiece  #HeavyRotation  #Nostalgia  #GoldenHour']::text[], '2026-08-31T18:13:33.934Z'::timestamptz)
ON CONFLICT (id) DO NOTHING;
