VALUES ('pxof2siuxVRVx6LrE8pw', 'dXFr4pizMtPx4qlZD3xgmralB3e2', '{"trackViewUrl":"https://music.apple.com/us/album/madhubala/1893887901?i=1893888086&uo=4","album":"Songs of Love","artwork":"https://is1-ssl.mzstatic.com/image/thumb/Music211/v4/4c/d2/57/4cd257b7-c052-3ecb-5d8c-1dbd612963b1/820233070478.jpg/600x600bb.jpg","previewUrl":"https://audio-ssl.itunes.apple.com/itunes-assets/AudioPreview221/v4/05/d2/cc/05d2ccde-64f1-8b9c-9a7a-7a0d35b24133/mzaf_9884614878796077434.plus.aac.p.m4a","youtubeSearchUrl":"https://www.youtube.com/results?search_query=Amit%20Trivedi%20Madhubala%20official%20audio","durationMs":243333,"artist":"Amit Trivedi","youtubeEmbedUrl":"https://www.youtube-nocookie.com/embed?listType=search&list=Amit%20Trivedi%20Madhubala&autoplay=1","id":"itunes-1893888086","title":"Madhubala","genre":"Indian Pop","youtubeMusicUrl":"https://music.youtube.com/search?q=Amit%20Trivedi%20Madhubala"}'::jsonb, 5, 'Seeing The Extraordinary', E'this is such a sweet song.\nthe beauty that lies in the simplest of things, and celebarting and appreciating people you meet from all walks of life.', '“Samajh se hai parey, ye tera jaadoo.”', 'Euphoric', ARRAY['#Masterpiece', '#HiddenGem']::text[], '2026-09-04T13:11:04.426Z'::timestamptz)
