VALUES ('rTHMt7LtbAJz4F601S4x', '2J8VmV1rBKMlJEnBvKWQN1MBklI2', '{"durationMs":249818,"artist":"Achint, Arijit Singh, Anumita Nadesan & Varun Grover","youtubeMusicUrl":"https://music.youtube.com/search?q=Achint%2C%20Arijit%20Singh%2C%20Anumita%20Nadesan%20%26%20Varun%20Grover%20Tenu%20Sang%20Rakhna%20(From%20%22Jigra%22)","previewUrl":"https://audio-ssl.itunes.apple.com/itunes-assets/AudioPreview211/v4/8a/a4/13/8aa41332-43d0-a96a-f160-786a1dd12b1c/mzaf_4096254739983246644.plus.aac.p.m4a","id":"itunes-1772023291","genre":"Bollywood","youtubeEmbedUrl":"https://www.youtube-nocookie.com/embed?listType=search&list=Achint%2C%20Arijit%20Singh%2C%20Anumita%20Nadesan%20%26%20Varun%20Grover%20Tenu%20Sang%20Rakhna%20(From%20%22Jigra%22)&autoplay=1","youtubeSearchUrl":"https://www.youtube.com/results?search_query=Achint%2C%20Arijit%20Singh%2C%20Anumita%20Nadesan%20%26%20Varun%20Grover%20Tenu%20Sang%20Rakhna%20(From%20%22Jigra%22)%20official%20audio","title":"Tenu Sang Rakhna (From \"Jigra\")","trackViewUrl":"https://music.apple.com/us/album/tenu-sang-rakhna-from-jigra/1772023287?i=1772023291&uo=4","artwork":"https://is1-ssl.mzstatic.com/image/thumb/Music211/v4/64/a8/ec/64a8ec39-1628-2f14-0ec7-ddf7b466cac4/198846455389.jpg/600x600bb.jpg","album":"Tenu Sang Rakhna (From \"Jigra\") - Single"}'::jsonb, 5, 'The best lines for being the eldest version in siblings', 'I loved the song just because the last song I have heard till now because of festival "Raksha Bandhan". It reminds me of my brother and being a protective sister always being by his side and helping him out in his bad times and good times too.', '"Vaddi ton vaddi, Koi vi foj aawe  Tenu sang rakhna  Taara na disse, Ya chaann kho jaawe  Tenu sang rakhna"', 'Nostalgic', ARRAY['#HiddenGem', '#Masterpiece', '#Nostalgia']::text[], '2026-08-31T18:34:11.366Z'::timestamptz)
