INSERT INTO public.posts (id, user_id, track, rating, headline, review, favorite_lyric, mood, vibe_tags, created_at)
VALUES ('soIVgH0JbPfOSQ8s0Jl5', 'KCOIDCHqp6bQxjJiI0RUaydoNOi2', '{"genre":"Bollywood","title":"Le Aaunga (From \"Satyaprem Ki Katha\")","youtubeSearchUrl":"https://www.youtube.com/results?search_query=Arijit%20Singh%2C%20Tanishk%20Bagchi%20%26%20Vayu%20Le%20Aaunga%20(From%20%22Satyaprem%20Ki%20Katha%22)%20official%20audio","artwork":"https://is1-ssl.mzstatic.com/image/thumb/Music126/v4/06/1b/09/061b0958-899e-6d6a-ae4a-f00cfa7d5a9d/8903431947550_cover.jpg/600x600bb.jpg","previewUrl":"https://audio-ssl.itunes.apple.com/itunes-assets/AudioPreview221/v4/17/48/23/174823a2-50d5-06be-27e0-529e6128b40b/mzaf_9992142015384978574.plus.aac.p.m4a","album":"Le Aaunga (From \"Satyaprem Ki Katha\") - Single","artist":"Arijit Singh, Tanishk Bagchi & Vayu","spotifyUrl":"https://open.spotify.com/search/Arijit%20Singh%2C%20Tanishk%20Bagchi%20%26%20Vayu%20Le%20Aaunga%20(From%20%22Satyaprem%20Ki%20Katha%22)","trackViewUrl":"https://music.apple.com/us/album/le-aaunga-from-satyaprem-ki-katha/1695278790?i=1695278791&uo=4","youtubeEmbedUrl":"https://www.youtube-nocookie.com/embed?listType=search&list=Arijit%20Singh%2C%20Tanishk%20Bagchi%20%26%20Vayu%20Le%20Aaunga%20(From%20%22Satyaprem%20Ki%20Katha%22)&autoplay=1","youtubeMusicUrl":"https://music.youtube.com/search?q=Arijit%20Singh%2C%20Tanishk%20Bagchi%20%26%20Vayu%20Le%20Aaunga%20(From%20%22Satyaprem%20Ki%20Katha%22)","id":"itunes-1695278791","durationMs":244053}'::jsonb, 5, 'When Love Promises to Find Its Way Back ❤️', 'A beautiful song that feels like a promise wrapped in emotions. The lyrics, melody, and vocals come together so naturally that you can’t help but feel every word. It has that perfect mix of love, longing, and hope. ✨', 'Rahe door jo tu jaake, sar saamne jhuka ke....... Phir se tujhe mana ke, le aaunga......... Shikwe sabhi bhula ke, naye raaste bana ke, Dil mein tujhe basa ke le aaunga ❤️', 'Euphoric', ARRAY['#HeavyRotation', '#MidnightDrive', '#HiddenGem', '#RainyDay', '#Masterpiece', '#GoldenHour', '#Nostalgia']::text[], '2026-09-14T08:48:49.964Z'::timestamptz)
