VALUES ('yojD32KTudacVwJvMaAz', 'kwXsKn7BsgYDrGVnEKSodnfAepi1', '{"genre":"Indian","youtubeEmbedUrl":"https://www.youtube-nocookie.com/embed?listType=search&list=Shravan%20Sridhar%20%26%20The%20Non%20Violinist%20Project%20Ulaa%20(feat.%20Sathyaprakash)&autoplay=1","trackViewUrl":"https://music.apple.com/us/album/ulaa-feat-sathyaprakash/1828746438?i=1828746439&uo=4","previewUrl":"https://audio-ssl.itunes.apple.com/itunes-assets/AudioPreview221/v4/b3/95/68/b39568f4-a866-89eb-2b1d-285132d1c6ce/mzaf_5904870341190016407.plus.aac.p.m4a","youtubeSearchUrl":"https://www.youtube.com/results?search_query=Shravan%20Sridhar%20%26%20The%20Non%20Violinist%20Project%20Ulaa%20(feat.%20Sathyaprakash)%20official%20audio","youtubeMusicUrl":"https://music.youtube.com/search?q=Shravan%20Sridhar%20%26%20The%20Non%20Violinist%20Project%20Ulaa%20(feat.%20Sathyaprakash)","durationMs":265288,"title":"Ulaa (feat. Sathyaprakash)","artist":"Shravan Sridhar & The Non Violinist Project","id":"itunes-1828746439","album":"Ulaa (feat. Sathyaprakash) - Single","artwork":"https://is1-ssl.mzstatic.com/image/thumb/Music211/v4/e7/d8/ac/e7d8accb-6482-e503-d1e3-dafb32988b2d/198000676797.jpg/600x600bb.jpg"}'::jsonb, 5, 'For me, this song sounds like home. 🌿', 'This has been one of my recent favourites. ❤️ Every time I hear it, I think of my hometown in the Nilgiris—the trees, the nature, the quiet, and that feeling of peace. The song may be about someone you love, but somehow, for me, it became a song about the place I was born.', 'Tedal teeradadhu...', 'Nostalgic', ARRAY['#HeavyRotation', '#Nostalgia', '#RainyDay', '#GoldenHour', '#HiddenGem']::text[], '2026-09-01T16:43:50.470Z'::timestamptz)
ON CONFLICT (id) DO NOTHING;

